package com.acme.order.inventory;
import com.acme.order.api.inventory.InventoryDtos.*;import com.acme.order.common.core.*;import jakarta.validation.Valid;import org.slf4j.MDC;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/internal/inventory") public class InventoryController {private final InventoryService service;private final InventoryRepository repo;public InventoryController(InventoryService s,InventoryRepository r){service=s;repo=r;}@PostMapping("/reserve") ApiResponse<Void> reserve(@Valid @RequestBody ReserveRequest r){service.reserve(r);return ApiResponse.ok(null,MDC.get("traceId"));}@PostMapping("/confirm") ApiResponse<Integer> confirm(@RequestBody ChangeRequest r){return ApiResponse.ok(service.confirm(r.orderNo()),MDC.get("traceId"));}@PostMapping("/release") ApiResponse<Integer> release(@RequestBody ChangeRequest r){return ApiResponse.ok(service.release(r.orderNo()),MDC.get("traceId"));}@GetMapping("/{sku}") ApiResponse<StockView> stock(@PathVariable long sku){return ApiResponse.ok(repo.stock(sku),MDC.get("traceId"));}}
